/* PsgDptcnyTrnsPrfmncMapper.upsertList */ MERGE INTO PMOWN.TN_PM_PSG_DPTCNY_TRNS_PRFMNC A USING (
SELECT #{item.totYmd} AS TOT_YMD, #{item.totTm} AS TOT_TM, #{item.totMnt} AS TOT_MNT, #{item.tmnlId} AS TMNL_ID, #{item.psgFcltCd} AS PSG_FCLT_CD, #{item.fltnm} AS FLTNM, #{item.bdpsgPrcsCnt} AS BDPSG_PRCS_CNT FROM DUAL
) B ON ( A.TOT_YMD = B.TOT_YMD AND A.TOT_TM = B.TOT_TM AND A.TOT_MNT = B.TOT_MNT AND A.TMNL_ID = B.TMNL_ID AND A.PSG_FCLT_CD = B.PSG_FCLT_CD AND A.FLTNM = B.FLTNM ) WHEN MATCHED THEN UPDATE SET A.BDPSG_PRCS_CNT = B.BDPSG_PRCS_CNT, A.LAST_MDFR_ID = #{regId}, A.LAST_MDFR_IP_ADDR = #{regIp}, A.LAST_MDFCN_DT = SYSTIMESTAMP WHEN NOT MATCHED THEN INSERT (TOT_YMD, TOT_TM, TOT_MNT, TMNL_ID, PSG_FCLT_CD, FLTNM, BDPSG_PRCS_CNT, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT) VALUES (B.TOT_YMD, B.TOT_TM, B.TOT_MNT, B.TMNL_ID, B.PSG_FCLT_CD, B.FLTNM, B.BDPSG_PRCS_CNT, #{regId}, #{regIp}, SYSTIMESTAMP)
